from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    dp = [[float('inf')] * (k + 1) for _ in range(n)]
    dp[0][0] = grid[0][0]

    for i in range(1, n):
        for j in range(k + 1):
            if j == 0:
                dp[i][j] = grid[i][0]
            else:
                for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < k and dp[nx][ny] != float('inf'):
                        dp[i][j] = min(dp[i][j], dp[nx][ny] + grid[i][j])

    return dp[n-1][k]
```

